"""Shared visual tokens for the two local FR5 interfaces."""

STYLE = """
:root{--ground:#eef1ef;--paper:#fff;--ink:#192d29;--muted:#536760;--accent:#176348;--soft:#e0ebe5;--warn:#f3e7c9;--error:#a52d35}
*{box-sizing:border-box}body{margin:0;background:var(--ground);color:var(--ink);font:16px/1.5 "Segoe UI",Arial,sans-serif}button,input,select{font:inherit}button,select{cursor:pointer}button{background:var(--accent);color:var(--paper);border:0;border-radius:4px;padding:12px 20px;font-weight:600;min-height:46px}button:hover{filter:brightness(.92)}button:active{transform:translateY(1px)}button:disabled{opacity:.5;cursor:not-allowed}input,select{border:1px solid #8d9e96;border-radius:4px;background:var(--paper);color:var(--ink);padding:12px;min-height:46px}a{color:inherit}a:focus-visible,button:focus-visible,select:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:4px}.topbar{padding:18px 32px;background:var(--ink);color:var(--paper);display:flex;justify-content:space-between;align-items:center;gap:20px}.brand{font-size:20px;font-weight:750;letter-spacing:-.5px}.topbar span{color:#cbdbd4;font-size:14px}.intro{padding:38px 32px 26px;display:flex;justify-content:space-between;align-items:end;gap:24px}h1{font-size:clamp(32px,4vw,48px);letter-spacing:-1.7px;line-height:1.1;margin:0 0 14px}h2{font-size:21px;letter-spacing:-.5px;margin:0 0 18px}p{margin:8px 0;color:var(--muted)}.intro p{max-width:650px}.notice{background:var(--warn);color:#59461d;padding:12px 18px;border-radius:4px;font-size:14px}.muted{color:var(--muted)}.panel{background:var(--paper);padding:28px;border-radius:6px}.section-head{display:flex;justify-content:space-between;gap:20px;align-items:center}.secondary{background:var(--soft);color:var(--ink)}#message{font-size:14px;min-height:24px;color:var(--accent)}#error{color:var(--error)}small{font-size:14px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;max-height:350px;overflow:auto}summary{cursor:pointer;font-weight:600;padding:6px 0}button,select,a{transition:background .15s,transform .15s}footer{padding:24px 32px;color:var(--muted);font-size:14px}@media(max-width:700px){.topbar{padding:16px 20px}.topbar span{max-width:140px;text-align:right}.intro{padding:28px 20px 22px;display:block}.intro>div+div{margin-top:20px}.panel{padding:22px}.notice{margin-top:16px}h1{letter-spacing:-1px}}@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
"""
